const body = $('Webhook').first().json.body;
const decoded = Buffer.from(body.message.data, 'base64').toString('utf-8');
const jsonData = JSON.parse(decoded);
const order = jsonData.afterData;

// Pedix solo manda el código de cada grupo de opciones, no su nombre.
// Acá decimos cómo se llama cada uno y de qué tipo es:
//   agregar = se suma algo   sacar = se saca algo
const GRUPOS = {
  'b83yR1ow51aXqvlUfVxR': { titulo: 'EXTRAS EN HAMBURGUESA', tipo: 'agregar' },
  'vNzEFea7bLYQ8yZrByNn': { titulo: 'EXTRAS EN PAPAS FRITAS', tipo: 'agregar' }, // varias hamburguesas
  'v2XoUUllSAs2Z3a7LgBB': { titulo: 'EXTRAS EN PAPAS FRITAS', tipo: 'agregar' }, // TASTYVAL
  '7fV3BBkdCxhKl0WG1lXz': { titulo: 'SIN', tipo: 'sacar' },                      // DOBLE CUARTO
  'fc7rcxt5QnIFvmQqIv2o': { titulo: 'SIN', tipo: 'sacar' },                      // TASTYVAL
  'f5FgqRaHXkQ1bmQYzpCW': { titulo: 'SIN', tipo: 'sacar' },                      // DOBLE y TRIPLE
  'hEdLabu4sOg0TVjvDWbg': { titulo: 'SIN', tipo: 'sacar' },                      // SUPER P
};

// Marca que usamos en el texto para que la pantalla sepa de qué color dibujarlo
const MARCAS = { agregar: '+', sacar: '-', otro: '*' };

// Línea de título de un grupo, por ejemplo "[-] SIN"
function encabezadoDeGrupo(grupoId, opciones) {
  const conocido = GRUPOS[grupoId];
  if (conocido) return `[${MARCAS[conocido.tipo]}] ${conocido.titulo}`;

  // Grupo que todavía no conocemos: si cuesta plata es un extra,
  // si no, lo mostramos neutro para no inventar un "SIN".
  // Se muestra el código para poder agregarlo a la tabla de arriba.
  const cuesta = opciones.some((o) => o.price > 0);
  const tipo = cuesta ? 'agregar' : 'otro';
  const titulo = cuesta ? 'EXTRAS' : 'OPCIONES';
  return `[${MARCAS[tipo]}] ${titulo} (grupo nuevo: ${grupoId})`;
}

// Un bloque por producto: el producto, sus grupos con lo elegido y su nota
const productos = order.cartItems.map((item) => {
  const lineas = [`${item.qty}x ${item.productName}`];

  for (const seleccion of item.selectedOptions || []) {
    // Pedix manda cada grupo así: { option: { id }, items: [ ... ] }
    const grupoId = seleccion.option ? seleccion.option.id : seleccion.id;
    const opciones = seleccion.items || [];
    if (opciones.length === 0) continue; // grupo sin nada elegido: no se muestra

    lineas.push(encabezadoDeGrupo(grupoId, opciones));
    for (const opcion of opciones) {
      const cantidad = opcion.quantity > 1 ? `${opcion.quantity}x ` : '';
      lineas.push(`- ${cantidad}${opcion.name}`);
    }
  }

  if (item.observations) lineas.push(`! ${item.observations}`);
  return lineas.join('\n');
}).join('\n');

// Pedix copia la nota de cada producto dentro de la observación general
// ("PILETA DE CHEDDAR: ..."). La sacamos para que no se repita.
let general = order.observations || '';
for (const item of order.cartItems) {
  if (item.observations) {
    general = general.split(`${item.productName}: ${item.observations}`).join('');
  }
}
general = general
  .replace(/(\s*[\n;,]\s*){2,}/g, '\n')
  .replace(/^[\s,;|\-]+|[\s,;|\-]+$/g, '');

return [{
  json: {
    pedix_id: String(order.id),
    cliente_nombre: order.personalInformation?.name || null,
    tipo_entrega: order.isDelivery ? 'envio' : 'retiro',
    productos: productos,
    observaciones: general || null,
  },
}];
